steps.content:
# LuckPerms configuration
server: {{ server_name }}
storage-method: {{ storage_method }}
use-server-uuid-cache: true
allow-invalid-usernames: {{ "true" if allow_invalid_usernames == "1" else "false" }}
auto-op: {{ "true" if auto_op == "1" else "false" }}
primary-group-calculation: parents-by-weight
argument-based-command-permissions: false
log-notify: true
